window.kbPageData["cards/d303985e853c4e079edb2fad"] = {"qs":{"国考 2025 行政执法 行测#91":{"paper":"国考 2025 行政执法 行测","n":91,"mod":"判断推理","src":["d8efe4e19862104d89c8.pdf",18],"asrc":["e2c4b1970d2b49eac0fd.pdf",29],"m":[],"task":"依据题给汛期定义，核对各类汛期的包含关系、别称和季节先后，识别错误判断。","current_affairs":{"state":"否","event":null,"year":null,"basis":"依据题给汛期定义和季节顺序作答。"},"links":[{"id":"k-129fa9d3fa8e0c34","label":"题设中凌汛和伏汛的发生季节","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"伏汛是发生在夏季三伏前后的汛水，凌汛是春季河冰解冻引起的涨水现象","why":"按题设口径，春季解冻凌汛属于春汛，夏季三伏前后的伏汛属于夏汛，季节归属决定二者的先后。","origin":"逐题标记"},{"id":"s-d45531f0ca63ae30","label":"比对概念或对象之间的关系","catalog_id":"L05","type":null,"role":"直接考查","field":"answer","quote":"夏季在春季后","why":"将两类汛期映射到各自所属季节，再用季节顺序核对题中陈述。","origin":"逐题标记"}],"stem":"流域内降雨或融冰化雪都可以引起河水显著上涨。春季，气候转暖，流域内的季节性积雪融化、河流解冻或春\n雨，引起河水上涨称春汛。因正值桃花盛开时节，故亦称桃汛。我国北方，把春季河冰解冻引起的涨水现象专称为\n凌汛。夏季，流域内的暴雨或高山冰川和积雪融化，使河水急剧上涨，称夏汛。我国习惯上把发生在夏季三伏前后\n的汛水称为伏汛。秋季由于暴雨，河水发生急剧上涨称秋汛。\n\n根据上述定义，下列判断错误的是：","options":["春汛包含凌汛","夏汛包含伏汛","伏汛在凌汛前","春汛就是桃汛"],"answer":"C","analysis":"91. 正确答案：C\n解析：\n第一步：找出定义关键词。\n春汛、桃汛：“春季，流域内的季节性积雪融化、河流解冻或春雨，引起河水上涨”、“因正值桃花盛开时节，故亦称\n桃汛”；\n凌汛：“春季河冰解冻引起的涨水现象”；\n夏汛：“夏季，流域内的暴雨或高山冰川和积雪融化，使河水急剧上涨”；\n伏汛：“发生在夏季三伏前后的汛水”；\n秋汛：“秋季由于暴雨，河水发生急剧上涨”。\n第二步：逐一分析选项。\nA项：凌汛是春季河冰解冻引起的涨水现象，说明是在春季因河流解冻引起的河水上涨，属于春汛的一种，所以春汛\n包含凌汛，判断正确，排除；\nB项：伏汛是发生在夏季三伏前后的汛水，说明是在夏季发生的河水上涨，属于夏汛的一种，所以夏汛包含伏汛，判\n断正确，排除；\nC项：伏汛是发生在夏季三伏前后的汛水，凌汛是春季河冰解冻引起的涨水现象，夏季在春季后，所以伏汛在凌汛\n后，判断错误，当选；\nD项：春汛的发生因正值桃花盛开时节，故亦称桃汛，所以春汛就是桃汛，判断正确，排除。\n本题为选非题，故正确答案为C。\n【考点】\n特殊问法","figs":[],"state":"已标记","notes":[],"domains":["地理"],"nature":"综合题","current":false},"国考 2025 行政执法 行测#92":{"paper":"国考 2025 行政执法 行测","n":92,"mod":"判断推理","src":["d8efe4e19862104d89c8.pdf",19],"asrc":["e2c4b1970d2b49eac0fd.pdf",29],"m":[],"task":"判断各例引用时是否只保留了原词语中部分字眼的意义，找出未采用断取修辞的一项。","current_affairs":{"state":"否","event":null,"year":null,"basis":"依据题内修辞定义判断。"},"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"question","quote":"只截取其中部分字眼的意义，而置其余于不顾","why":"根据语境核对引用时保留了哪些字眼的意义。","origin":"逐题标记"}],"stem":"断取是修辞格的一种，引用词语时，只截取其中部分字眼的意义，而置其余于不顾，是一种“断章取义”的修辞方\n式。\n根据上述定义，下列没有采用断取修辞方式的是:","options":["相较于他之前见过的大阵仗，眼前的情形在他眼中就是“小儿科”","小林一心扑在科研项目上，他至今还是一个“光杆司令”呢","山林发生火灾，消防员“上刀山下火海”，奋力保卫人民的生命和财产安全","实在走投无路，他最终还是找老师“开药方”，问询这一困局的破解之道"],"answer":"D","analysis":"92. 正确答案：D\n解析：\n第一步：找出定义关键词。\n“引用词语时，只截取其中部分字眼的意义，而置其余于不顾”。\n第二步：逐一分析选项。\nA项：该项引用“小儿科”时，只取“小”义而舍“儿科”义，表明了眼前的情形在他眼中只是小阵仗，符合“引用词语时，\n只截取其中部分字眼的意义，而置其余于不顾”，符合定义，排除；\nB项：该项引用“光杆司令”时，只取“光杆”义而舍“司令”义，表明了小林因搞科研而至今未成婚，仍独身一人，符\n合“引用词语时，只截取其中部分字眼的意义，而置其余于不顾”，符合定义，排除；\n\nC项：该项引用“上刀山下火海”时，只取“下火海”义而舍“上刀山”义，突出了消防员在扑救大火时不畏艰难险阻的勇敢\n精神，符合“引用词语时，只截取其中部分字眼的意义，而置其余于不顾”，符合定义，排除；\nD项：该项引用“开药方”时，用了其完整的意思，表明了他在走投无路时，找老师寻求解决方法，不符合“引用词语\n时，只截取其中部分字眼的意义，而置其余于不顾”，不符合定义，当选。\n本题为选非题，故正确答案为D。\n【考点】\n单定义-其他句式","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false},"国考 2025 行政执法 行测#93":{"paper":"国考 2025 行政执法 行测","n":93,"mod":"判断推理","src":["d8efe4e19862104d89c8.pdf",19],"asrc":["e2c4b1970d2b49eac0fd.pdf",30],"m":[],"task":"根据题内定义核对各研究实例的对象与分析方式，判断哪一项属于细胞化学的研究范围。","current_affairs":{"state":"否","event":null,"year":null,"basis":"依据题内研究范围判断。"},"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"answer","quote":"是对细胞内化学成分“核酸”和“蛋白质”做定量分析","why":"将测定组分含量的研究实例对应到题内的定量分析条件。","origin":"逐题标记"}],"stem":"细胞化学是研究细胞的化学成分及其在细胞活动中的变化和定位的学科。具体来说，细胞化学是在不破坏细胞形\n态结构的状况下，用生化的和物理的技术对细胞的各种组分做定量分析，研究其动态变化，了解细胞代谢过程中各\n种细胞组分的作用。\n根据上述定义，下列属于细胞化学研究范围的是：","options":["观察玉米根系细胞从周围环境中摄取营养的能力以及受环境影响产生的活动","根据哺乳动物细胞内核酸、蛋白质吸收不同紫外光的特点，分析其含量","抽取患者骨髓液，根据显微镜下骨髓细胞的不同形态，判断患者的疾病种类","研究小鼠免疫细胞受病原体侵入后，病原体释放毒素杀死免疫细胞的动态过程"],"answer":"B","analysis":"93. 正确答案：B\n解析：\n第一步：找出定义关键词。\n“研究细胞的化学成分及其在细胞活动中的变化和定位”、“在不破坏细胞形态结构的状况下”、“对细胞的各种组分做定\n量分析”、“了解细胞代谢过程中各种细胞组分的作用”。\n第二步：逐一分析选项。\nA项：观察玉米根系细胞摄取营养的能力及受环境影响产生的活动，不涉及细胞的化学成分，也没有对细胞的各种组\n分做定量分析，不符合“研究细胞的化学成分及其在细胞活动中的变化和定位”、“对细胞的各种组分做定量分析”，不\n符合定义，排除；\nB项：分析哺乳动物细胞内核酸、蛋白质的含量，是对细胞内化学成分“核酸”和“蛋白质”做定量分析，符合“研究细胞\n的化学成分及其在细胞活动中的变化和定位”、“对细胞的各种组分做定量分析”，符合定义，当选；\nC项：根据显微镜下“骨髓细胞的不同形态”来判断患者的疾病种类，不是研究细胞的化学成分，也没有对细胞的各种\n组分做定量分析，不符合“研究细胞的化学成分及其在细胞活动中的变化和定位”、“对细胞的各种组分做定量分析”，\n不符合定义，排除；\nD项：研究小鼠免疫细胞被病原体杀死的动态过程，其研究的是“病原体”释放毒素杀死免疫细胞的过程，不是研究免\n疫细胞的各种组分，不符合“研究细胞的化学成分及其在细胞活动中的变化和定位”、“对细胞的各种组分做定量分\n析”，不符合定义，排除。\n故正确答案为B。\n【考点】\n定义-方式目的","figs":[],"state":"已标记","notes":[],"domains":["科技"],"nature":"技能题","current":false}},"materialFiles":{},"terms":{"k-129fa9d3fa8e0c34":{"id":"k-129fa9d3fa8e0c34","mode":"k","type":"概念与词义","title":"凌汛与伏汛的季节（题设）","qs":[],"count":1},"s-d45531f0ca63ae30":{"id":"s-d45531f0ca63ae30","mode":"s","type":"判断推理","title":"类比关系与词项顺序","qs":[],"count":108},"s-conditions":{"id":"s-conditions","mode":"s","type":"判断推理","title":"按题内定义核对案例条件","qs":[],"count":149}},"questions":{}};
